class Exercise {
    // 외부에서 잔액을 직접 바꾸지 못하게 해요.
    private int balance=100;
    boolean withdraw(int amount) {
        // 이 조건이 상태의 규칙을 지켜요.
        if(amount<0) return false;
        balance-=amount;
        return true;
    }
    // 검사에서 현재 상태를 확인해요.
    int balance(){return balance;}
}
